 void SMS_init (void) {
   // Initializes the lib
   unsigned char i;
   /* make sure the VDP is ready */
   while (VDPVCounterPort!=0xB0);
   /* extra care in case the BIOS had left the VDP registers with weird config */
   while (VDPVCounterPort!=0xC8);
   /* set sprite palette color 0 to black */
 #ifndef TARGET_GG
   SMS_setSpritePaletteColor(0, RGB(0,0,0));
 #else
   GG_setSpritePaletteColor(0, RGB(0,0,0));
 #endif
   /* VDP initialization */
   for (i=0;i<sizeof(VDPReg_init);i++)
     SMS_write_to_VDPRegister(i,VDPReg_init[i]);
   /* reset sprites */
   SMS_initSprites();
   SMS_copySpritestoSAT();
 #ifndef TARGET_GG
   /* init Pause (SMS only) */
   SMS_resetPauseRequest();
 #ifdef VDPTYPE_DETECTION
   /* PAL/NTSC detection (SMS only) */
   DISABLE_INTERRUPTS;
   unsigned char detected=SMS_detect_VDP_type();
   ENABLE_INTERRUPTS;
   if (detected==0xF2)
     VDPType=VDP_PAL;
   else if (detected==0xDA)
     VDPType=VDP_NTSC;
 #endif
   SMS_theLineInterruptHandler=outi_block;  // to fix the issues with the ED X7 snapshots
 #endif
 }

