    def test_literal_and_repeat(self):
        assets.validate_stream(bytes((0x82, 1, 2, 0, 2, 3, 0)), (2, 2))

    def test_invalid_streams(self):
        cases = (
            (bytes((0x80,)), (1,)),
            (bytes((0x82, 1)), (2,)),
            (bytes((2,)), (2,)),
            (bytes((1, 42)), (1,)),
            (bytes((1, 42, 0, 7)), (1,)),
            (bytes((1, 42, 0)), (2,)),
            (bytes((0x7f, 42)) * 25 + bytes((0,)), (3175,)),
        )
        for data, lengths in cases:
            with self.subTest(data=data, lengths=lengths):
                with self.assertRaises(ValueError):
