 def convert_files(asm_dir, names, relocatable, headers=True):
     asm_dir = Path(asm_dir)
     conv = Converter(relocatable)
     out = []
     if headers:
         out.append("; Generated by tools/port_asm.py from the original disassembly. Do not edit.")
         out.append("\t.module original_game" if relocatable else "\t.module original_rom")
         out.append("\t.area _CODE" if relocatable else "\t.area _ABS (ABS)\n\t.org 0x0000")
     for entry in names:
         name, first, last, symbol = ((entry, 1, None, None) if isinstance(entry, str)
                                      else (tuple(entry) + (None,))[:4])
         out.append(f"; ---- {name}")
         if relocatable and name in BANKED_FILES:
             out.append("\t.area _BANK2")
         if symbol:
             target = f"orig_entry_{len(conv.wrappers)}"
             conv.wrappers.append((symbol, target))
             out.append(target + ":")
         for raw in (asm_dir / name).read_text().splitlines()[first - 1:last]:
             converted = conv.line(raw, asm_dir)
             if converted:
                 out.append(converted)
         if relocatable and name in BANKED_FILES:
             out.append("\t.area _CODE")
     return conv, "\n".join(out) + "\n"


 def convert_relocatable(asm_dir):
     conv, source = convert_files(asm_dir, GAMEPLAY_FILES, True)
     externals = sorted(u for u in conv.used if u not in conv.defined)
     missing = [t for t in (*EXPORTS, *ALIASES) if t not in conv.defined]
     if missing:
         raise SystemExit(f"Exported labels not found in converted files: {missing}")
     lines = ["\t.globl " + name for name in externals]
     lines.append("; ---- C-callable wrappers: preserve IX/IY as the SDCC ABI requires")
     for symbol, target in conv.wrappers:
         lines += [f"{symbol}::", "\tpush ix", "\tpush iy", f"\tcall {target}", "\tpop iy", "\tpop ix",
                   "\tret"]
     return source + "\n".join(lines) + "\n", externals


 def parse_ihx(text):
     memory = {}
     for line in text.splitlines():
         if not line.startswith(":"):
             continue
         count = int(line[1:3], 16)
         address = int(line[3:7], 16)
         if int(line[7:9], 16) != 0:
             continue
         for i in range(count):
             memory[address + i] = int(line[9 + 2 * i:11 + 2 * i], 16)
     return memory


